const FOOTER="<footer class=\"footer\" id=\"footer\"><div class=\"footer-inner\"><div class=\"topline\"><div><div class=\"tag\">LAMINATE, by Sentinel</div><h2>Discover lesions.<br><em>Follow their story.</em></h2><p class=\"invitation\">Take a closer look at LAMINATE, together.<br>Bring your team and your questions.</p></div><div class=\"demo-block\"><button class=\"cta\" data-demo>Let\u2019s explore your workflow <span class=\"arrow\" aria-hidden=\"true\"><svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up-right\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n</svg>\n</span></button><p class=\"demo-caption\">A conversation shaped around your team.</p></div></div><div class=\"grid\"><div class=\"brand-col\"><a class=\"footer-logo\" href=\"#top\" aria-label=\"Sentinel Cloud Service home\"><img src=\"data:image/svg+xml;base64,\" alt=\"Sentinel Cloud Service\"></a><p class=\"brand-copy\">Sentinel Cloud Service.<br>The company behind LAMINATE.</p><a class=\"product-badge\" href=\"#product\" data-preview=\"Product\">LAMINATE <span>Our MRI analysis product <svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up-right\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n</svg>\n</span></a></div><div class=\"column\"><h3>Explore LAMINATE</h3><a href=\"#single\" data-preview=\"Single Timepoint Analysis\">Single timepoint analysis</a><a href=\"#longitudinal\" data-preview=\"Longitudinal Analysis\">Longitudinal analysis</a><a href=\"#review\" data-preview=\"Interactive Review\">Interactive review</a><a href=\"#workflow\" data-preview=\"PACS Workflow\">PACS workflow</a></div><div class=\"column\"><h3>Get connected</h3><a href=\"#demo\" data-demo>Book a demo <svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up-right\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n</svg>\n</a><a href=\"#pricing\" data-demo>Talk about pricing</a><a href=\"#questions\" data-preview=\"Questions\">Questions & answers</a><a href=\"https://portal.laminate.nyuad.nyu.edu\" target=\"_blank\" rel=\"noopener\">Open the portal <svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up-right\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n</svg>\n</a></div><div class=\"column deployment\"><h3>Built around your workflow</h3><a href=\"#deployment\" data-preview=\"Deployment\">Cloud & enterprise options <svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up-right\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n</svg>\n</a><p>Cloud hosting with an on-site PACS gateway, or custom deployment using your own infrastructure and GPUs.</p></div></div><div class=\"bottom\"><span>\u00a9 <span class=\"year\"></span> Sentinel Cloud Service.<br>For clinicians, hospitals and researchers worldwide.</span><button class=\"back\" aria-label=\"Back to top\">Back to top <span aria-hidden=\"true\"><svg aria-hidden=\"true\" focusable=\"false\" class=\"icon icon-arrow-up\"\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"m5 12 7-7 7 7\" />\n  <path d=\"M12 19V5\" />\n</svg>\n</span></button></div></div></footer>";
class SentinelElement extends HTMLElement {
  static get observedAttributes() { return ['theme','compact','links','current-path','config']; }
  constructor() { super(); this.attachShadow({mode:'open'}); }
  connectedCallback() {
    if(this.controller) return;
    this.controller=new AbortController();
    const header=this.tagName.toLowerCase()==='sentinel-header';
    this.shadowRoot.innerHTML='<style>@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&display=swap");'+STYLE+`\n:host{display:block;width:100%;font-family:'IBM Plex Sans',sans-serif;color:var(--ink)}.shell{font:15px 'IBM Plex Sans',sans-serif}.header{position:relative;transform:none;left:auto;top:0;margin:auto}.header.is-compact{top:0;margin-top:12px}.shell.dark{--paper:#0e1112;--surface:#161a1c;--ink:#edeae2;--teal:#5c9a93;--soft:#1e2e2c;--line:#262a2c}.navigation a[aria-current="page"]:after{transform:scaleX(1)}@media(max-width:900px){.header.menu-open .navigation{position:relative;top:auto;flex-basis:100%;order:3;width:100%;margin-top:8px;box-shadow:none}.header.menu-open{flex-wrap:wrap}.header-brand{margin-right:auto}}.footer{min-height:100%}`+'</style><div class="shell">'+(header?HEADER:FOOTER)+'</div>';
    this.shell=this.shadowRoot.querySelector('.shell');
    const signal=this.controller.signal;
    this.shadowRoot.addEventListener('click',e=>{
      const a=e.target.closest('a'),button=e.target.closest('button');
      if(a?.dataset.routeKey){this.setMenu(false);return;}
      if(button?.matches('.theme-toggle')) {
        const theme=this.getAttribute('theme')==='dark'?'light':'dark';
        this.setAttribute('theme',theme);
        try{localStorage.setItem('sentinel-theme',theme);}catch{}
        window.dispatchEvent(new CustomEvent('sentinel-theme-sync',{detail:{theme,source:this}}));
        this.dispatchEvent(new CustomEvent('sentinel-theme',{detail:{theme}}));
      } else if(button?.matches('.mobile-toggle')) this.setMenu(!this.shadowRoot.querySelector('.header').classList.contains('menu-open'));
      else if(button?.matches('.back')){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});this.dispatchEvent(new CustomEvent('sentinel-top'));}
      else if(button?.matches('[data-demo]') || a?.matches('[data-demo]')) {e.preventDefault();this.navigate('demo');}
      else if(a && a.getAttribute('href')?.startsWith('#')) {e.preventDefault();this.navigate(a.dataset.preview||'home');}
      if(a) this.setMenu(false);
    },{signal});
    this.shadowRoot.addEventListener('keydown',e=>{if(e.key==='Escape'){this.setMenu(false);this.shadowRoot.querySelector('.mobile-toggle')?.focus();}},{signal});
    this.resize=new ResizeObserver(()=>this.reportSize());this.resize.observe(this.shell);
    this.shadowRoot.querySelector('.year')?.replaceChildren(String(new Date().getFullYear()));
    this.arrowTemplate=this.shadowRoot.querySelector('.login svg, .column a svg')?.cloneNode(true)||null;
    this.applyConfig();
    try{const saved=localStorage.getItem('sentinel-theme');if(saved==='dark'||saved==='light')this.setAttribute('theme',saved);}catch{}
    // Keep header and footer in the same theme: each broadcasts its change, the other follows.
    window.addEventListener('sentinel-theme-sync',e=>{
      if(e.detail.source!==this&&this.getAttribute('theme')!==e.detail.theme)this.setAttribute('theme',e.detail.theme);
    },{signal});
    // Close the mobile menu on an outside click or when the viewport leaves the mobile layout.
    document.addEventListener('click',e=>{if(!e.composedPath().includes(this))this.setMenu(false);},{signal});
    matchMedia('(max-width: 900px)').addEventListener('change',()=>this.setMenu(false),{signal});
    // The header shrinks to the floating bar after 88px of scrolling and returns near the top.
    if(header&&this.getAttribute('auto-compact')!=='false'){
      let compact=false,queued=false;
      const update=()=>{queued=false;const y=window.scrollY;const next=compact?y>40:y>88;if(next!==compact){compact=next;this.setAttribute('compact',String(compact));}};
      window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update);}},{passive:true,signal});
      update();
    }
    this.apply();
    this.dispatchEvent(new CustomEvent('sentinel-ready'));
  }

  // Everything the header and footer say or link to comes from the `config` attribute (JSON).
  // Text is always set as text, never as HTML, so CMS content cannot inject markup.
  applyConfig(){
    if(!this.shell)return;
    let cfg=null;try{cfg=JSON.parse(this.getAttribute('config')||'null');}catch{}
    if(!cfg)return;
    const root=this.shadowRoot,arrow=()=>this.arrowTemplate?this.arrowTemplate.cloneNode(true):null;
    const text=(sel,value)=>{const el=root.querySelector(sel);if(el&&typeof value==='string')el.textContent=value;return el;};
    const setLabel=(el,value)=>{if(!el||typeof value!=='string')return;const n=[...el.childNodes].find(c=>c.nodeType===3&&c.textContent.trim());if(n)n.textContent=value+' ';else el.prepend(document.createTextNode(value+' '));};
    const link=(item,extra)=>{
      const a=document.createElement('a');a.textContent=item.label||'';a.href=item.url||'#';
      if(item.newTab){a.target='_blank';a.rel='noopener';const ic=arrow();if(ic){a.append(' ');a.append(ic);}}
      if(item.demo)a.setAttribute('data-demo','');
      if(extra)a.className=extra;return a;
    };
    const brand=cfg.brand||{};
    if(brand.name)root.querySelectorAll('.brand, .footer-logo').forEach(a=>{a.setAttribute('aria-label',brand.name+' home');});
    if(brand.name)root.querySelectorAll('.wordmark, .footer-logo img').forEach(i=>{i.alt=brand.name;});
    if(brand.homeUrl)root.querySelectorAll('.brand, .footer-logo').forEach(a=>{a.href=brand.homeUrl;a.dataset.routeKey='';delete a.dataset.routeKey;});
    this.demoUrl=(cfg.header&&cfg.header.cta&&cfg.header.cta.url)||(cfg.footer&&cfg.footer.cta&&cfg.footer.cta.url)||this.demoUrl;

    const h=cfg.header;
    if(h){
      const nav=root.querySelector('.navigation');
      if(nav&&Array.isArray(h.nav)){
        nav.replaceChildren(...h.nav.map(i=>link(i)));
        if(h.signIn)nav.append(link(h.signIn,'mobile-extra'));
      }
      const login=root.querySelector('.login');
      if(login&&h.signIn){login.href=h.signIn.url||'#';login.target=h.signIn.newTab===false?'':'_blank';setLabel(login,h.signIn.label);}
      if(h.cta){text('.cta .long-label',h.cta.label);text('.cta .short-label',h.cta.shortLabel||h.cta.label);}
    }
    const f=cfg.footer;
    if(f){
      text('.tag',f.tag);
      const h2=root.querySelector('.footer .topline h2');
      if(h2&&typeof f.headline==='string'){const em=document.createElement('em');em.textContent=f.headlineEmphasis||'';h2.replaceChildren(f.headline,document.createElement('br'),em);}
      const inv=root.querySelector('.invitation');if(inv&&typeof f.invitation==='string'){inv.replaceChildren(...f.invitation.split('\n').flatMap((t,i)=>i?[document.createElement('br'),t]:[t]));}
      if(f.cta)setLabel(root.querySelector('.demo-block .cta'),f.cta.label);
      text('.demo-caption',f.caption);
      const bc=root.querySelector('.brand-copy');if(bc&&typeof f.brandCopy==='string'){bc.replaceChildren(...f.brandCopy.split('\n').flatMap((t,i)=>i?[document.createElement('br'),t]:[t]));}
      const pb=root.querySelector('.product-badge');
      if(pb&&f.product){pb.href=f.product.url||'#';const sp=pb.querySelector('span');setLabel(pb,f.product.label);if(sp)setLabel(sp,f.product.sub);}
      const grid=root.querySelector('.footer .grid');
      if(grid&&Array.isArray(f.columns)){
        grid.querySelectorAll('.column').forEach(c=>c.remove());
        f.columns.forEach(col=>{
          const d=document.createElement('div');d.className='column'+(col.text?' deployment':'');
          const t=document.createElement('h3');t.textContent=col.title||'';d.append(t);
          (col.links||[]).forEach(i=>d.append(link(i)));
          if(col.text){const p=document.createElement('p');p.textContent=col.text;d.append(p);}
          grid.append(d);
        });
      }
      const bottom=root.querySelector('.bottom > span');
      if(bottom&&typeof f.legal==='string'){const y=document.createElement('span');y.className='year';y.textContent=String(new Date().getFullYear());bottom.replaceChildren('© ',y,' ',...f.legal.split('\n').flatMap((t,i)=>i?[document.createElement('br'),t]:[t]));}
    }
    this.apply();
  }
  disconnectedCallback(){this.controller?.abort();this.controller=null;this.resize?.disconnect();}
  attributeChangedCallback(name){if(name==='config')this.applyConfig();this.apply();}
  apply(){
    if(!this.shell)return;
    const dark=this.getAttribute('theme')==='dark';
    this.shell.classList.toggle('dark',dark);
    this.shadowRoot.querySelector('.header')?.classList.toggle('is-compact',this.getAttribute('compact')==='true');
    const t=this.shadowRoot.querySelector('.theme-toggle');
    if(t){t.setAttribute('aria-pressed',String(dark));t.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');}
    let links={};try{links=JSON.parse(this.getAttribute('links')||'{}');}catch{}
    this.links=links;
    this.shadowRoot.querySelectorAll('a').forEach(a=>{
      const key=a.dataset.preview||(a.hasAttribute('data-demo')?'demo':a.classList.contains('brand')||a.classList.contains('footer-logo')?'home':null);
      if(key && links[key]){a.href=links[key];a.dataset.routeKey=key;}
      const active=a.getAttribute('href')===this.getAttribute('current-path');
      if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');
    });
    // Velo owns navigation, including Wix anchors and page transitions.
    this.shadowRoot.querySelectorAll('a[data-route-key]').forEach(a=>{
      if(a.dataset.bound)return;a.dataset.bound='true';
      a.addEventListener('click',e=>{if(e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();this.navigate(a.dataset.routeKey);},{signal:this.controller.signal});
    });
  }
  navigate(key){this.setMenu(false);this.dispatchEvent(new CustomEvent('sentinel-navigate',{detail:{key,url:key==='demo'?this.demoUrl:undefined}}));}
  setMenu(open){const h=this.shadowRoot.querySelector('.header'),t=this.shadowRoot.querySelector('.mobile-toggle');if(!h)return;h.classList.toggle('menu-open',open);t.setAttribute('aria-expanded',String(open));t.setAttribute('aria-label',open?'Close navigation':'Open navigation');this.reportSize();}
  reportSize(){const height=Math.ceil(this.shell.getBoundingClientRect().height);if(height===this.lastHeight)return;this.lastHeight=height;this.style.height=height+'px';this.dispatchEvent(new CustomEvent('sentinel-size',{detail:{height}}));}
}
if(!customElements.get('sentinel-header'))customElements.define('sentinel-header',class extends SentinelElement{});
if(!customElements.get('sentinel-footer'))customElements.define('sentinel-footer',class extends SentinelElement{});
